 void order(String n,String p,String ad,String items,int sub,String coupon){if(busy)return;busy=true;pn=n;pp=p;pa=ad;pi=items;ps=sub;pc=coupon==null?"":coupon.trim().toUpperCase(Locale.US);discount=0;if(sub<100){busy=false;js("window.orderError('Minimum order is ₹100.');");return;}if(a.getCurrentUser()==null)a.signInAnonymously().addOnSuccessListener(x->locate());else locate();}
 void locate(){if(Build.VERSION.SDK_INT>=23&&ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);js("window.locationRequired&&window.locationRequired();");return;}LocationManager m=(LocationManager)getSystemService(LOCATION_SERVICE);Location l=null;try{l=m.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(l==null)l=m.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);}catch(Exception e){}if(l!=null){distance(l);return;}try{m.requestSingleUpdate(LocationManager.NETWORK_PROVIDER,new LocationListener(){public void onLocationChanged(Location x){distance(x);}},null);}catch(Exception e){busy=false;js("window.orderError('Location could not be read. Please enable GPS.');");}}
 void distance(Location l){if(!busy)return;float[] d={0};Location.distanceBetween(l.getLatitude(),l.getLongitude(),LAT,LON,d);double km=d[0]/1000;js("window.locationResult&&window.locationResult("+JSONObject.quote(String.format(Locale.US,"%.2f",km))+");");if(km>R){busy=false;pn=null;js("window.orderError('Delivery is available only within 5 km of Nansa Gate, Nawalgarh.');");return;}create();}
 String itemName(String id){ String[] ids={"samosa","kachori","mirchi","dahi1","dahi2","pizza","wraps","momos","burger","pasta","manchurian","kajukatli","rasgulla","rajbhog","gulabjamun","sohanpapdi","milkcake","kalakand","dilkushal","peda","petha","namkin","rasmalai","curd"}; String[] names={"Samosa","Kachori","Mirchi Bada","Dahi Bhalla Plate 1","Dahi Bhalla Plate 2","Pizza","Wraps","Momos","Burger","Pasta","Manchurian","Kaju Katli","Rasgulla","Rajbhog","Gulab Jamun","Sohan Papdi","Milk Cake","Kalakand","Dilkushal","Peda","Petha","Namkin","Rasmalai","Dahi (Curd)"}; for(int i=0;i<ids.length;i++) if(ids[i].equals(id)) return names[i]; return id; }
 void create(){if(!busy||a.getCurrentUser()==null)return;busy=true;Runnable save=()->{try{Map<String,Object>o=new HashMap<>();o.put("userId",a.getCurrentUser().getUid());o.put("customerName",pn);o.put("mobile",pp);o.put("address",pa);o.put("paymentMethod","COD");o.put("subtotal",ps);o.put("deliveryFee",30);o.put("discount",discount);o.put("couponCode",pc);o.put("total",ps+30-discount);o.put("status","PLACED");o.put("createdAt",FieldValue.serverTimestamp());JSONArray ar=new JSONArray(pi);Map<String,Object>im=new HashMap<>();for(int i=0;i<ar.length();i++){JSONObject z=ar.getJSONObject(i);Map<String,Object> iv=new HashMap<>(); String iid=z.getString("id"); iv.put("id",iid); iv.put("name",itemName(iid)); iv.put("qty",z.getInt("qty")); im.put(iid,iv);}o.put("items",im);db.collection("orders").add(o).addOnSuccessListener(r->{getPreferences(0).edit().putString("lastOrderId",r.getId()).putString("lastOrderItems",pi).apply();listen(r.getId());busy=false;pn=null;js("window.orderCreated("+JSONObject.quote(r.getId())+");");}).addOnFailureListener(e->{busy=false;js("window.orderError("+JSONObject.quote("Order save failed: "+e.getMessage())+");");});}catch(Exception e){busy=false;js("window.orderError('Order data is invalid.');");}};
  if(pc.isEmpty()){save.run();return;}db.collection("coupons").document(pc).get().addOnSuccessListener(c->{if(!c.exists()||!Boolean.TRUE.equals(c.getBoolean("enabled"))){busy=false;js("window.orderError('Invalid or inactive coupon.');");return;}Long min=c.getLong("minOrder");if(min!=null&&ps<min){busy=false;js("window.orderError('Minimum order for this coupon is ₹"+min+".');");return;}String type=c.getString("type");Long val=c.getLong("value");long v=val==null?0:val;discount="PERCENT".equals(type)?Math.min((long)ps,((long)ps*v)/100):Math.min((long)ps,v);save.run();}).addOnFailureListener(e->{busy=false;js("window.orderError('Coupon validation failed.');");});
 }
 void listen(String id){if(sl!=null)sl.remove();sl=db.collection("orders").document(id).addSnapshotListener((s,e)->{if(e!=null||s==null||!s.exists())return;String st=s.getString("status");if(st==null)st="PLACED";js("window.statusUpdate("+JSONObject.quote(st)+");");if(!st.equals(last)){last=st;if(!st.equals("PLACED")&&(Build.VERSION.SDK_INT<33||ActivityCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED))((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%100000),new NotificationCompat.Builder(this,CH).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Samosa King – Order Update").setContentText("Order status: "+st).setAutoCancel(true).build());}});}
