 void history(){if(a.getCurrentUser()==null){js("window.renderHistory('[]')");return;}db.collection("orders").whereEqualTo("userId",a.getCurrentUser().getUid()).get().addOnSuccessListener(s->{try{List<DocumentSnapshot>l=new ArrayList<>(s.getDocuments());l.sort((x,y)->{Date dx=x.getDate("createdAt"),dy=y.getDate("createdAt");return dy==null?-1:dx==null?1:dy.compareTo(dx);});JSONArray out=new JSONArray();for(DocumentSnapshot d:l.subList(0,Math.min(30,l.size()))){JSONObject o=new JSONObject();o.put("id",d.getId());o.put("total",d.getLong("total")!=null?d.getLong("total"):0);o.put("status",String.valueOf(d.get("status")));o.put("date",d.getDate("createdAt")!=null?d.getDate("createdAt").toString():"Recent");Map<String,Object>im=d.get("items",Map.class);JSONArray ia=new JSONArray();if(im!=null)for(Map.Entry<String,Object>q:im.entrySet()){JSONObject z=new JSONObject();z.put("id",q.getKey());Object vv=q.getValue();if(vv instanceof Map){Map<?,?> mm=(Map<?,?>)vv;z.put("name",String.valueOf(mm.get("name")));z.put("qty",num(mm.get("qty")));}else{z.put("name",itemName(q.getKey()));z.put("qty",num(vv));}ia.put(z);}o.put("itemsJson",ia.toString());out.put(o);}js("window.renderHistory("+JSONObject.quote(out.toString())+");");}catch(Exception e){js("window.renderHistory('[]')");}}).addOnFailureListener(e->js("window.renderHistory('[]')"));}
 long num(Object x){if(x instanceof Number)return ((Number)x).longValue();try{return Long.parseLong(String.valueOf(x));}catch(Exception e){return 0;}}
